import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AppLogger } from '../../common/logger/app-logger';
import { ReworkEventCenterHourBucketDto } from './dtos/rework-event-center-hour-bucket.dto';
import {
  addHours,
  formatLocalDateTime,
  toHourStart,
  toHourValue,
} from './rework-list-date.helper';
import { ReworkList } from './rework-list.entity';

@Injectable()
export class ReworkListService {
  public constructor(
    @InjectRepository(ReworkList)
    private readonly reworkListRepository: Repository<ReworkList>,
    private readonly customLogger: AppLogger,
  ) {}

  public async getOne(id: number, plant: number): Promise<ReworkList | null> {
    return this.reworkListRepository.findOne({ where: { id, plant } });
  }

  public async getReworkCountByDateRange(
    plant: number,
    resourceId: string,
    startDate: Date,
    endDate: Date,
  ): Promise<number> {
    try {
      const result = await this.reworkListRepository
        .createQueryBuilder('rework_list')
        .select('SUM(rework_list.quantity)', 'totalQuantity')
        .where('rework_list.plant = :plant', { plant })
        .andWhere('rework_list.resource_id = :resourceId', { resourceId })
        .andWhere('rework_list.creation_date >= :startDate', { startDate })
        .andWhere('rework_list.creation_date <= :endDate', { endDate })
        .getRawOne();
      return result?.totalQuantity || 0;
    } catch (error) {
      this.customLogger.error('Error in getReworkCountByDateRange:', error);
      return 0;
    }
  }

  public async getReworksForEventCenterByHour(
    plant: number,
    resourceId: string,
    startDate: Date,
    endDate: Date,
  ): Promise<Array<ReworkEventCenterHourBucketDto>> {
    try {
      const reworks = await this.reworkListRepository
        .createQueryBuilder('rework_list')
        .leftJoin(
          'scrap_reason',
          'rework_cause',
          'rework_cause.plant = rework_list.plant AND rework_cause.mii_code = rework_list.mii_rework_code',
        )
        .leftJoin(
          'scrap_reason',
          'rework_sub_cause',
          'rework_sub_cause.plant = rework_list.plant AND rework_sub_cause.mii_code = rework_list.mii_second_rework_code',
        )
        .select([
          'rework_list.plant AS plant',
          'rework_list.id AS id',
          'rework_list.creation_date AS creationDate',
          'rework_list.material_id AS materialId',
          'rework_list.quantity AS quantity',
          'rework_list.resource_id AS resourceId',
          'rework_list.work_center_id AS workCenterId',
          'rework_list.mii_rework_code AS miiReworkCode',
          'rework_list.mii_second_rework_code AS miiSecondReworkCode',
          'rework_list.rework_comment AS reworkComment',
          'rework_cause.mii_reason AS cause',
          'rework_sub_cause.mii_reason AS subCause',
        ])
        .where('rework_list.plant = :plant', { plant })
        .andWhere('rework_list.resource_id = :resourceId', { resourceId })
        .andWhere('rework_list.creation_date >= :startDate', { startDate })
        .andWhere('rework_list.creation_date < :endDate', { endDate })
        .orderBy('rework_list.creation_date', 'ASC')
        .getRawMany();

      const mappedReworks = reworks.map((rework) => ({
        cause: rework.cause,
        creationDate: formatLocalDateTime(new Date(rework.creationDate)),
        id: Number(rework.id),
        materialId: rework.materialId,
        miiReworkCode: rework.miiReworkCode,
        miiSecondReworkCode: rework.miiSecondReworkCode,
        plant: Number(rework.plant),
        quantity: Number(rework.quantity),
        resourceId: rework.resourceId,
        reworkComment: rework.reworkComment,
        subCause: rework.subCause,
        workCenterId: rework.workCenterId,
      }));

      const buckets = new Map<string, ReworkEventCenterHourBucketDto>();

      for (
        let currentHour = toHourStart(startDate);
        currentHour < endDate;
        currentHour = addHours(currentHour, 1)
      ) {
        let hourEnd = addHours(currentHour, 1);
        if (hourEnd > endDate) {
          hourEnd = endDate;
        }
        const bucketKey = currentHour.getTime().toString();

        buckets.set(bucketKey, {
          hour: toHourValue(currentHour),
          hourEnd: formatLocalDateTime(hourEnd),
          hourStart: formatLocalDateTime(currentHour),
          reworks: [],
        });
      }

      for (const rework of mappedReworks) {
        const hourStart = toHourStart(new Date(rework.creationDate));
        const bucketKey = hourStart.getTime().toString();
        const bucket = buckets.get(bucketKey);

        if (bucket) {
          bucket.reworks.push(rework);
        }
      }

      return [...buckets.values()];
    } catch (error) {
      this.customLogger.error(
        'Error in getReworksForEventCenterByHour:',
        error,
      );
      return [];
    }
  }
}

