      throw error;
    }
  }

  public async getScrapsForEventCenterByHour(
    plant: number,
    resourceId: string,
    startDate: Date,
    endDate: Date,
  ): Promise<Array<ScrapEventCenterHourBucketDto>> {
    try {
      const scraps = await this.scrapListRepository
        .createQueryBuilder('scrap_list')
        .leftJoin(
          'scrap_reason',
          'scrap_cause',
          'scrap_cause.plant = scrap_list.plant AND scrap_cause.mii_code = scrap_list.mii_scrap_code',
        )
        .leftJoin(
          'scrap_reason',
          'scrap_sub_cause',
          'scrap_sub_cause.plant = scrap_list.plant AND scrap_sub_cause.mii_code = scrap_list.mii_second_scrap_code',
        )
        .select([
          'scrap_list.plant AS plant',
          'scrap_list.scrap_list_id AS scrapListId',
          'scrap_list.creation_date AS creationDate',
          'scrap_list.material_id AS materialId',
          'scrap_list.quantity AS quantity',
          'scrap_list.resource_id AS resourceId',
          'scrap_list.mii_scrap_code AS miiScrapCode',
          'scrap_list.mii_second_scrap_code AS miiSecondScrapCode',
          'scrap_list.scrap_type_code AS scrapTypeCode',
          'scrap_list.scrap_comment AS scrapComment',
          'scrap_cause.mii_reason AS cause',
          'scrap_sub_cause.mii_reason AS subCause',
        ])
        .where('scrap_list.plant = :plant', { plant })
        .andWhere('scrap_list.resource_id = :resourceId', { resourceId })
        .andWhere('scrap_list.creation_date >= :startDate', { startDate })
        .andWhere('scrap_list.creation_date < :endDate', { endDate })
        .orderBy('scrap_list.creation_date', 'ASC')
        .getRawMany();

      const mappedScraps = scraps.map((scrap) => ({
        plant: Number(scrap.plant),
        scrapListId: scrap.scrapListId,
        creationDate: formatLocalDateTime(new Date(scrap.creationDate)),
        materialId: scrap.materialId,
        quantity: Number(scrap.quantity),
        resourceId: scrap.resourceId,
        miiScrapCode: scrap.miiScrapCode,
        miiSecondScrapCode: scrap.miiSecondScrapCode,
        scrapTypeCode: scrap.scrapTypeCode,
        scrapComment: scrap.scrapComment,
        cause: scrap.cause,
        subCause: scrap.subCause,
      }));

      const buckets = new Map<string, ScrapEventCenterHourBucketDto>();

      for (
        let currentHour = toHourStart(startDate);
        currentHour < endDate;
        currentHour = addHours(currentHour, 1)
      ) {
        let hourEnd = addHours(currentHour, 1);
        if (hourEnd > endDate) {
          hourEnd = endDate;
        }
        const bucketKey = currentHour.getTime().toString();
        const hourValue = pad(currentHour.getHours());

        buckets.set(bucketKey, {
          hour: hourValue,
          hourStart: formatLocalDateTime(currentHour),
          hourEnd: formatLocalDateTime(hourEnd),
          scraps: [],
        });
      }

      for (const scrap of mappedScraps) {
        const hourStart = toHourStart(new Date(scrap.creationDate));
        const bucketKey = hourStart.getTime().toString();
        const bucket = buckets.get(bucketKey);

        if (bucket) {
          bucket.scraps.push(scrap);
        }
      }

      return [...buckets.values()];
    } catch (error) {
      this.customLogger.error(
        `Failed to retrieve scraps for event center: ${error.message}`,
      );

      throw error;
    }
  }
}

